mapper.update:
UPDATE TB_QSTN_ANS
   SET QSTN_CN = #{qstnCn},
       ANS_CN = #{ansCn, jdbcType=VARCHAR},
       RQT_MTTR_SN = #{rqtMttrSn, jdbcType=NUMERIC}
 WHERE QSTN_ANS_SN = #{qstnAnsSn}

mapper.select:
SELECT B.PBANC_SN AS pbancSn, B.BID_PBANC_NO AS bidPbancNo, B.PBANC_NM AS pbancNm, Q.CNT AS qnaCnt
  FROM TB_BID_PBANC B
  JOIN TB_PRP_TMMBR M ON M.PBANC_SN = B.PBANC_SN AND M.USER_ID = #{userId}
  JOIN (SELECT PBANC_SN, COUNT(*) AS CNT FROM TB_QSTN_ANS GROUP BY PBANC_SN) Q ON Q.PBANC_SN = B.PBANC_SN
 WHERE B.PBANC_SN <> #{pbancSn}
 ORDER BY B.PBANC_SN DESC
